int listenfd = socket(AF_INET, SOCK_STREAM, 0);

struct sockaddr_in serveraddr;
bzero(&serveraddr, sizeof(serveraddr));
serveraddr.sin_family = AF_INET;
serveraddr.sin_addr.s_addr = htonl(INADDR_ANY);
serveraddr.sin_port = htons(PORT);

bind(listenfd, (SA *)&serveraddr, sizeof(serveraddr));

listen(listenfd, LISTENQ);

int connfd = accept(listenfd, (SA *)&clientaddr, &clientlen);
close(listenfd);

// ---

int clientfd = socket(AF_INET, SOCK_STREAM, 0);
// serveraddr populated

if (connect(clientfd, (SA *)&serveraddr, sizeof(serveraddr)) < 0) {
    // Connection failed
}

char buf[] = "Request";
ssize_t bytes_sent = send(clientfd, buf, strlen(buf), 0);

char rbuf[MAX_BUF];
ssize_t bytes_recv = recv(clientfd, rbuf, MAX_BUF, 0);

close(clientfd);

// ---

// ECF Handling: Ignoring SIGPIPE 
// (Writing to a closed socket causes SIGPIPE default)
struct sigaction sa;
sa.sa_handler = SIG_IGN; 
sigemptyset(&sa.sa_mask);
sa.sa_flags = 0;
sigaction(SIGPIPE, &sa, NULL);

// Alternative: Use MSG_NOSIGNAL flag (preferred)
ssize_t n = send(sockfd, data, len, MSG_NOSIGNAL);

if (n < 0 && (errno == EPIPE || errno == ECONNRESET)) {
    // Peer disconnected gracefully
    return -1; 
}
